DROP TABLE IF EXISTS `cospay_order`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `cospay_order` (
  `id` bigint(20) NOT NULL,
  `addtime` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `pay_order_no` varchar(64) NOT NULL COMMENT '支付单号',
  `order_no` varchar(64) NOT NULL COMMENT '业务订单号(cosorder.order_no)',
  `user_id` bigint(20) DEFAULT NULL,
  `user_table` varchar(100) DEFAULT NULL,
  `amount` decimal(10,2) DEFAULT NULL COMMENT '支付金额',
  `pay_channel` varchar(50) DEFAULT 'mock' COMMENT '支付渠道: mock/wechat/alipay',
  `pay_status` varchar(50) DEFAULT '待支付' COMMENT '待支付/已支付/已关闭',
  `pay_url` varchar(500) DEFAULT NULL COMMENT '支付地址或二维码链接',
  `channel_trade_no` varchar(100) DEFAULT NULL COMMENT '渠道交易号',
  `expire_time` datetime DEFAULT NULL COMMENT '过期时间',
  `pay_time` datetime DEFAULT NULL COMMENT '支付时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_pay_order_no` (`pay_order_no`),
  KEY `idx_order_no` (`order_no`),
  KEY `idx_user` (`user_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='COS支付单';
/*!40101 SET character_set_client = @saved_cs_client */;

